#!/usr/bin/env bash
# Generate AVIF and WebP siblings for page hero images, and record their pixel
# sizes in _data/image_sizes.yml so _includes/page__hero.html can emit srcset,
# width, and height. Requires avifenc and cwebp (brew install libavif webp).
# Run from the repo root after adding or replacing a hero image, then commit
# the generated files.
set -euo pipefail

heroes=(
  assets/images/ivan-smiling-teaching-1752w.jpg
  assets/images/ivan-smiling-teaching-876w.jpg
  assets/images/ivan-monitor-blog.jpg
)

data=_data/image_sizes.yml
echo "# Generated by scripts/build-images.sh. Pixel sizes of hero images." > "$data"

for img in "${heroes[@]}"; do
  base="${img%.*}"
  avifenc --speed 4 -q 60 "$img" "$base.avif" > /dev/null
  cwebp -quiet -q 78 "$img" -o "$base.webp"
  width=$(sips -g pixelWidth "$img" | awk '/pixelWidth/ {print $2}')
  height=$(sips -g pixelHeight "$img" | awk '/pixelHeight/ {print $2}')
  printf '"/%s":\n  width: %s\n  height: %s\n' "$img" "$width" "$height" >> "$data"
  printf '%-48s jpg %7s  avif %7s  webp %7s\n' "$img" \
    "$(wc -c < "$img")" "$(wc -c < "$base.avif")" "$(wc -c < "$base.webp")"
done
